function serpbearPrompt({ body, domain }) {
  if (typeof domain !== "string" || !domain.trim() || domain === "YOUR_DOMAIN")
    throw Error("Configure domain");
  if (!body || typeof body !== "object" || !Array.isArray(body.keywords))
    throw Error("SerpBear did not return keywords");
  if (!body.keywords.length) return { hasKeywords: false, messages: [] };
  const rows = body.keywords.map((k) => {
    if (
      !k ||
      typeof k.keyword !== "string" ||
      !k.keyword.trim() ||
      (k.position != null && (!Number.isFinite(k.position) || k.position < 0)) ||
      (k.history != null && (typeof k.history !== "object" || Array.isArray(k.history))) ||
      typeof k.domain !== "string" ||
      k.domain !== domain ||
      (k.url != null && typeof k.url !== "string")
    )
      throw Error("Invalid keyword data");
    const position = k.position ?? 0,
      entries = Object.entries(k.history ?? {});
    if (
      entries.some(([date, v]) => !/^\d{4}-\d{2}-\d{2}$/.test(date) || !Number.isFinite(v) || v < 0)
    )
      throw Error("Invalid keyword history");
    const positions = entries
        .sort(([a], [b]) => a.localeCompare(b))
        .slice(-7)
        .map((x) => x[1])
        .filter((x) => x > 0),
      avg = positions.length
        ? Math.round((positions.reduce((a, b) => a + b, 0) / positions.length) * 10) / 10
        : null,
      trend =
        avg === null || position === 0
          ? "not enough ranking data"
          : position < avg
            ? "improving"
            : position > avg
              ? "declining"
              : "stable";
    return {
      keyword: k.keyword,
      currentPosition: position,
      averagePosition: avg,
      trend,
      url: k.url || "not ranking",
    };
  });
  const content = `You are an SEO expert. Analyze this keyword ranking data for ${domain}:\n${JSON.stringify(rows)}\nSummarize rankings in a table, identify improvements and issues, and suggest actions.`;
  return { hasKeywords: true, messages: [{ role: "user", content }] };
}

const result = serpbearPrompt({
  body: $input.first().json,
  domain: $("Configure SerpBear").first().json.domain,
});
return result.hasKeywords ? [{ json: result }] : [];

function reportRow({ completion, blog }) {
  if (typeof blog !== "string" || !blog.trim() || blog === "YOUR_BLOG_NAME")
    throw Error("Configure the blog name");
  const text = completion?.choices?.[0]?.message?.content;
  if (typeof text !== "string" || !text.trim()) throw Error("OpenRouter returned no report text");
  if (completion.choices[0].finish_reason === "length")
    throw Error("OpenRouter report was truncated");
  return { row: { Date: new Date().toISOString().slice(0, 10), Note: text, Blog: blog } };
}

return { json: reportRow({ completion: $json, blog: "YOUR_BLOG_NAME" }) };

function config({ instance, domain }) {
  if (
    typeof instance !== "string" ||
    instance.includes("YOUR_SERPBEAR_HOST") ||
    typeof domain !== "string" ||
    domain === "YOUR_DOMAIN" ||
    !domain.trim()
  )
    throw Error("Configure SerpBear instance and domain");
  if (
    !/^https:\/\/[a-z0-9](?:[a-z0-9.-]*[a-z0-9])?(?::[0-9]{1,5})?\/api\/keywords$/i.test(instance)
  )
    throw Error("Use an HTTPS SerpBear /api/keywords URL");
  return { url: instance, domain };
}

return [
  { json: config({ instance: "https://YOUR_SERPBEAR_HOST/api/keywords", domain: "YOUR_DOMAIN" }) },
];
